@ExceptionHandler(PayrollUnavailableException.class)
ProblemDetail handle(PayrollUnavailableException e) {
    log.debug("payroll down", e);
    ProblemDetail p = ProblemDetail.forStatus(503);
    p.setProperty("code", "employee.payroll_unavailable");
    p.setProperty("retryable", true);
    return p;
}

@Transactional
public void hire(HireRequest r) throws PayrollRejectedException {
    repo.save(new Employee(r));
    payroll.register(r);        // throws PayrollRejectedException (checked)
}
